import unittest
from solution import read_records
class Checks(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(read_records(''),[])
    def test_plain(self):
        self.assertEqual(read_records('a,b\nc,d\n'),[['a','b'],['c','d']])
    def test_quoted(self):
        self.assertEqual(read_records('"a,b","say ""hi"""\n'),[['a,b','say "hi"']])
    def test_multiline(self):
        self.assertEqual(read_records('"a\nb",c\r\nx,y\r\n'),[['a\nb','c'],['x','y']])
    def test_blanks_spaces_unicode(self):
        self.assertEqual(read_records(' a ,,"żółć😀",\n'),[[' a ','','żółć😀','']])
    def test_roundtrip(self):
        import csv,io
        for n in range(1,12):
            rows=[[str(i),'a,b','x"y','first\nsecond',''] for i in range(n)]
            stream=io.StringIO(newline='')
            csv.writer(stream).writerows(rows)
            self.assertEqual(read_records(stream.getvalue()),rows)

import copy,unittest
from solution import merge_intervals
class Checks(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(merge_intervals([]),[])
    def test_nested_touching_and_unsorted(self):
        self.assertEqual(merge_intervals([[7,8],[2,3],[1,5],[5,7]]),[[1,8]])
    def test_gaps_points_duplicates(self):
        self.assertEqual(merge_intervals([[4,4],[1,1],[1,1],[2,3]]),[[1,1],[2,3],[4,4]])
    def test_negative(self):
        self.assertEqual(merge_intervals([[-5,-1],[-2,2],[9,10]]),[[-5,2],[9,10]])
    def test_reverse_rejected(self):
        with self.assertRaises(ValueError): merge_intervals([[2,1]])
    def test_no_mutation_or_alias(self):
        data=[[5,7],[1,3]]
        before=copy.deepcopy(data)
        result=merge_intervals(data)
        self.assertEqual(data,before)
        result[0][0]=999
        self.assertEqual(data,before)
    def test_idempotence_and_coverage(self):
        for n in range(1,16):
            data=[[i-4,i-4+(i%3)] for i in range(n)]
            result=merge_intervals(data)
            self.assertEqual(merge_intervals(result),result)
            for x in [i/2 for i in range(-10,36)]:
                self.assertEqual(any(a<=x<=b for a,b in data),any(a<=x<=b for a,b in result))
            self.assertTrue(all(result[i][1]<result[i+1][0] for i in range(len(result)-1)))

import unittest
from solution import query_values
class Checks(unittest.TestCase):
    def test_empty(self):
        self.assertEqual(query_values(''),{})
    def test_repeated_empty_and_flag(self):
        self.assertEqual(query_values('x=1&x=&flag&=z'),{'x':['1',''],'flag':[''],'':['z']})
    def test_encoding(self):
        self.assertEqual(query_values('q=hello+world&x=%2B%26%3D&x=%252F'),{'q':['hello world'],'x':['+&=','%2F']})
    def test_unicode_keys(self):
        self.assertEqual(query_values('%C5%BC=%F0%9F%98%80'),{'ż':['😀']})
    def test_embedded_equals(self):
        self.assertEqual(query_values('x=a=b'),{'x':['a=b']})
    def test_roundtrip(self):
        from urllib.parse import urlencode
        pairs=[('a',''),('a','x+y'),('z','a&b'),('',''),('key =','żółć😀')]
        expected={}
        for k,v in pairs: expected.setdefault(k,[]).append(v)
        self.assertEqual(query_values(urlencode(pairs)),expected)

import math,unittest
from solution import moving_average
class Checks(unittest.TestCase):
    def test_full_windows(self):
        self.assertEqual(moving_average([2,4,6,8],2),[3,5,7])
        self.assertEqual(moving_average([2,4,6],3),[4])
    def test_empty_and_oversized(self):
        self.assertEqual(moving_average([],1),[])
        self.assertEqual(moving_average([1,2],3),[])
    def test_invalid_window(self):
        for w in [0,-1,True,False,1.0,'2',None]:
            with self.subTest(w=w),self.assertRaises(ValueError): moving_average([1,2],w)
    def test_invalid_elements_even_oversized(self):
        for value in [True,'2',None,float('nan'),float('inf'),float('-inf')]:
            for w in [1,10]:
                with self.subTest(value=value,w=w),self.assertRaises(ValueError): moving_average([value],w)
    def test_reference_and_no_mutation(self):
        for n in range(1,21):
            data=[((-1)**i)*i/3 for i in range(n)]
            before=list(data)
            for w in range(1,n+2):
                result=moving_average(data,w)
                expected=[math.fsum(data[i:i+w])/w for i in range(n-w+1)]
                self.assertEqual(len(result),len(expected))
                for a,b in zip(result,expected): self.assertAlmostEqual(a,b,places=10)
            self.assertEqual(data,before)

