{"source":"def merge_intervals(intervals):
    if not intervals:
        return []
    normalized = []
    for item in intervals:
        start, end = item
        if start > end:
            raise ValueError("start must not be greater than end")
        normalized.append([start, end])
    normalized.sort(key=lambda pair: (pair[0], pair[1]))
    merged = []
    for start, end in normalized:
        if merged and start <= merged[-1][1]:
            if end > merged[-1][1]:
                merged[-1][1] = end
        else:
            merged.append([start, end])
    return merged"}

{"source":"from urllib.parse import unquote

def query_values(query):
    if not query:
        return {}
    result = {}
    for part in query.split('&'):
        if '=' in part:
            key, value = part.split('=', 1)
        else:
            key, value = part, ''
        key = unquote(key.replace('+', ' '))
        value = unquote(value.replace('+', ' '))
        result.setdefault(key, []).append(value)
    return result"}

{"source":"import math

def moving_average(values, window):
    if isinstance(window, bool) or not isinstance(window, int) or window <= 0:
        raise ValueError("window must be a positive integer")
    for v in values:
        if isinstance(v, bool) or not isinstance(v, (int, float)):
            raise ValueError("values must contain only finite int or float")
        if isinstance(v, float) and not math.isfinite(v):
            raise ValueError("values must contain only finite int or float")
    n = len(values)
    if window > n:
        return []
    return [sum(values[i:i+window]) / window for i in range(n - window + 1)]"}
